/* ==========================================================================
   ProxCenter — English messages

   刻意声明成 Partial：**没翻的词条直接不写**，运行时会回退到中文原文，
   而不是留一条中英混杂的假翻译。想知道还剩多少没翻，比对两边的键即可：

     node -e "const {zhCN}=await import('./src/i18n/locales/zh-CN.ts')" 之类的脚本

   键必须来自 `MessageKey`，写错键名会编译报错。
   ========================================================================== */

