  'vmDetail.biosSwitchTitle': 'Switching from {from} to {to}',
  'vmDetail.biosSwitchBody': 'Firmware type is tied to the partition scheme and bootloader: an MBR install needs SeaBIOS, while a GPT + EFI install needs OVMF. Switching a machine that already has a system installed makes it fail to boot, and the only way back is reverting the value or reinstalling.',
