  'vmDetail.biosOvmfTitle': 'OVMF prerequisites',
  'vmDetail.biosOvmfBody': 'UEFI systems such as Windows 11 need OVMF together with an EFI variable disk (efidisk0) and the q35 machine type. All three go together — miss one and it will not start.',
