  'templates.bpMemoryBody': 'Do not give the template too little memory (≥ 1024 MB is a good floor). Then set the balloon minimum to a lower value (such as 1024) — without it PVE counts the full allocation, so the host cannot reclaim anything even when clones sit idle. Clones inherit this value, so setting it once on the template is enough.',
