  /* --------------------------------------------------------------- FAQ */
  'faq.q1': 'Does Proxmox need to be exposed to the public internet?',
  'faq.a1': 'No. The panel reaches the cluster over the internal network through the Proxmox API (port 8006 by default); only the panel itself needs to be reachable from outside.',
  'faq.q2': 'Why does the browser console need an extra Proxmox account?',
  'faq.a2': 'Proxmox does not allow an API token to call vncproxy; the console only accepts a ticket obtained with a username and password. The feature is optional and leaving it unset does not affect anything else.',
  'faq.q3': 'How does SSL certificate auto-renewal work?',
  'faq.a3': 'Taking a free Tencent Cloud DV certificate as an example: the certificate is valid for 90 days and the panel submits the renewal request automatically after the number of days you configure (15 days before expiry by default). Once the CA issues it, the panel downloads and redeploys the certificate to the target machine, then runs the reload command you configured (such as nginx -s reload).',
  'faq.q4': 'Does the Feishu bot need a public callback? Could someone abuse it?',
  'faq.a4': 'Yes: the bot reaches the panel through the event callback of the Feishu open platform, and the callback URL must be reachable from Feishu (reverse proxy or port forwarding works for internal deployments). Two layers of protection are in place: a group or user allowlist is required and messages from anyone else are rejected; and dangerous operations such as shutdown, reboot and rollback first show a confirmation card and only run once confirmed, with everything written to the audit log.',
  'settings.siteIcpPlaceholder': 'ICP licence number',
  'conn.fieldPort': 'API port',
  'conn.fieldPortHint': 'Proxmox VE defaults to 8006',
  'conn.fieldTokenId': 'API token ID',
  'conn.fieldTokenIdHint': 'Format: user@realm!tokenname',
  'conn.fieldTokenSecret': 'API token secret',
  'conn.secretHintConfigured': 'Leave blank to keep the existing credential',
  'conn.secretHintNew': 'Shown only once at creation',
  'conn.secretPlaceholderConfigured': 'Leave blank to keep the current secret',
  'conn.secretPlaceholder': 'Paste the token secret',
  'conn.hideSecret': 'Hide sensitive value',
  'conn.showSecret': 'Show sensitive value',
  'conn.optionsBlock': 'Connection options',
  'conn.optionsBlockHint': 'Certificate verification policy',
  'conn.verifySsl': 'Verify certificate (verify_ssl)',
  'conn.verifySslHint': 'Off by default for new connections (PVE usually uses a self-signed certificate); import a CA and enable it in production.',
  'conn.consoleBlock': 'Console credentials (optional)',
  'conn.consoleBlockHint': 'The VNC console only accepts a username and password',
