  'incident.worm1a': 'True immutability (WORM) must be guaranteed by the ',
  'incident.worm1b': 'storage side',
  'incident.worm1c':
    ': PBS retention/immutability, S3 Object Lock, or a read-only mounted filesystem. The PVE API alone cannot do it, and this page does not pretend otherwise.',
  'incident.worm2a': 'What this page offers is ',
  'incident.worm2b': 'detection-based',
  'incident.worm2c':
    ' protection: (1) the panel refuses to delete protected backups (ransomware would have to release the protection in the UI first, even with an admin session); (2) best-effort, PVE volumes get the ',
  'incident.worm2d':
    ' flag set (blocking PVE prune and normal deletes; root can still clear it); (3) periodically verify the backup still exists and its metadata is unchanged, alerting on anomalies.',
  'incident.worm3a':
    'Also: PVE does not provide a content checksum for vzdump archives, so "verify" compares ',
  'incident.worm3b': 'size and creation time',
  'incident.worm3c': ', which catches ',
  'incident.worm3d': 'deletion / replacement / metadata changes',
  'incident.worm3e':
    ', but cannot catch silent bit rot in the storage layer. Use PBS if you need that.',
