    'The panel process does not run as root, so it cannot read /etc/shadow and other files, nor change system configuration. Running the panel as root (or under a root systemd unit) unlocks every check and one-click hardening.',
  'baseline.readonlyRemote':
    'The SSH credentials for this host have no root / sudo rights: /etc/shadow and the system logs cannot be read, and configuration files cannot be written. Give it an account with passwordless sudo (tick "use sudo" under "SSH security → Hosts & alerts") and harden again.',
  'baseline.pendingTitle': 'To address ({n})',
  'baseline.pendingSubtitle':
    'Sorted by severity. Items that can be automated have a "Fix" button; handle the rest manually as advised',
  'baseline.fix': 'Fix',
  'baseline.fixNoPermTitle': 'No root / sudo rights, so it cannot be hardened',
  'baseline.allPassTitle': 'All checks passed',
  'baseline.allPassBody':
    'All {n} checks are satisfied; just keep inspecting regularly.',
  'baseline.catSubtitleIssues':
    '{total} checks · {fail} failing / {warn} improvable',
  'baseline.catSubtitleOk': 'All {total} checks passed',
  'baseline.scoreValue': '{n}',
  'baseline.policyTitle': 'Scope and hardening policy',
  'baseline.policyScopeLabel': 'What is inspected',
  'baseline.policyScope':
    ': every server on the platform — the panel host and the hosts enabled under "SSH security → Hosts & alerts". Both sides share the same decision logic in the backend, so the conclusions match; to inspect a Proxmox node in the cluster, add it as a managed host (the PVE API itself cannot run shell commands on a node).',
  'baseline.policyScoreLabel': 'How the score works',
  'baseline.policyScore':
    ': weighted by severity — high 3, medium 2, low 1, with "improvable" counting half; "not checkable" items stay out of the denominator, so missing permissions never cost you points unfairly.',
  'baseline.policyWriteLabel': 'What hardening writes',
  'baseline.policyWriteA': ': only files named by the panel — ',
  'baseline.policyWriteB': ' and ',
  'baseline.policyWriteC': '; ',
  'baseline.policyWriteD': ' is backed up before editing. SSH changes are validated immediately with ',
  'baseline.policyWriteE': ' and kernel parameters are re-read from the ',
  'baseline.policyWriteF': ' to confirm; if validation fails it ',
  'baseline.policyWriteG': 'rolls back automatically',
  'baseline.policyWriteH': ', so a machine is never left unable to log in.',
  'baseline.policyNoAutoLabel': 'What it never does automatically',
  'baseline.policyNoAuto':
    ': items that may lock you out, such as disabling SSH password authentication, require per-item confirmation and a separate fix; if a managed host connects with "root + password" or password authentication, the matching hardening is refused outright (otherwise the panel would lock itself out too). Environment-specific items such as the firewall, PAM complexity modules and UID 0 accounts only come with actionable manual advice.',
  'baseline.policyAuditLabel': 'Auditing',
  'baseline.policyAuditA': ': reading a report records ',
  'baseline.policyAuditB': ' / ',
  'baseline.policyAuditC': ', and hardening records ',
  'baseline.policyAuditD': ' / ',
  'baseline.policyAuditE': '.',
  'baseline.conclusionUnreachable':
    'This server cannot be inspected right now; first confirm it is reachable under "SSH security → Hosts & alerts".',
  'baseline.conclusionAllPass':
    'All {total} checks are satisfied; just keep inspecting regularly.',
  'baseline.conclusionFails':
    '{fail} failing and {warn} improvable; handle the failing high-severity items first.',
  'baseline.conclusionWarns':
    'No failing items, and {warn} more could be tightened.',

